    if (bg === "transparent") return true;
    if (!bg.startsWith('rgba(')) return false;
    var matchState = bg.match(bgColorRegexTS);
    if (!matchState || matchState.length !== 5) return false;
    var alpha = parseFloat(matchState[4], 10);
